package com.moapan.newsletter;
import com.moapan.newsletter.domain.PublicationResearch;
import com.moapan.newsletter.domain.PublicationResearch.*;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class PublicationResearchTest {
 final UUID id=UUID.fromString("10000000-0000-0000-0000-000000000001");final Instant now=Instant.parse("2026-10-30T08:00:00Z");final LocalDate week=LocalDate.parse("2026-10-26");
 Forecast forecast(List<UUID> ids){return new Forecast("Question","Observed evidence","Conditional scenario","Proposed 3 months","Experiment","Proposed threshold","Stop condition",ids);}
 Dossier draft(String start,String cutoff,List<UUID> ids,List<Forecast> forecasts,boolean rights,boolean review,String note){return new Dossier(start,cutoff,ids,forecasts,rights,review,note);}
 Dossier valid(){return draft(week.toString(),now.toString(),List.of(id),List.of(forecast(List.of(id))),true,true,"");}
 Evidence item(Instant collected,boolean visible){return new Evidence(id,"Synthetic evidence","https://example.org/paper",collected,visible);}
 List<String> check(Dossier d,List<Evidence> refs,List<String> links,boolean revision){return PublicationResearch.blockers(d,refs,links,now,week,revision);}
 @Test void koreanWeekAndInclusiveCollectionBoundaries(){assertEquals(week,PublicationResearch.week(Instant.parse("2026-10-25T15:00:00Z")));assertEquals(LocalDate.parse("2026-10-19"),PublicationResearch.week(Instant.parse("2026-10-25T14:59:59Z")));for(var time:List.of(PublicationResearch.start(week),now))assertTrue(check(valid(),List.of(item(time,true)),List.of("https://example.org/paper"),false).isEmpty());}
 @Test void outsideCutoffOldFutureAndUncollectedReferencesAreBlocked(){for(var time:List.of(PublicationResearch.start(week).minusNanos(1),now.plusNanos(1)))assertTrue(check(valid(),List.of(item(time,true)),List.of(),false).contains("evidence_outside_week"));assertTrue(check(valid(),List.of(item(now,true)),List.of("https://uncollected.example/paper"),false).contains("uncollected_reference"));assertTrue(check(valid(),List.of(),List.of(),false).contains("evidence_unavailable"));assertTrue(check(valid(),List.of(item(now,false)),List.of(),false).contains("evidence_unavailable"));}
 @Test void rightsReviewForecastReferencesAndRevisionNoteAreRequired(){assertTrue(check(null,List.of(),List.of(),false).contains("research_required"));assertTrue(check(draft(week.toString(),now.toString(),List.of(id),List.of(forecast(List.of(UUID.randomUUID()))),false,false,""),List.of(item(now,true)),List.of(),true).containsAll(List.of("forecast_evidence_required","reuse_rights_review_required","editorial_review_required","correction_note_required")));assertTrue(check(draft(week.toString(),now.toString(),List.of(id),List.of(forecast(List.of(id))),true,true,"Clarified a proposed threshold"),List.of(item(now,true)),List.of(),true).isEmpty());}
 @Test void historicalRevisionKeepsOriginalWeekCutoff(){Instant nextWeek=now.plusSeconds(10*86400);Instant end=PublicationResearch.start(week.plusDays(7));assertEquals(end.minusNanos(1),PublicationResearch.cutoff(week,nextWeek));var d=draft(week.toString(),PublicationResearch.cutoff(week,nextWeek).toString(),List.of(id),List.of(forecast(List.of(id))),true,true,"Correction based on original evidence");assertTrue(PublicationResearch.blockers(d,List.of(item(now,true)),List.of(),nextWeek,week,true).isEmpty());}
 @Test void datesAndOversizedDraftMetadataCannotBypassGate(){for(String date:List.of("2026-10-27","2026-10-19","not-a-date"))assertTrue(check(draft(date,now.toString(),List.of(id),List.of(forecast(List.of(id))),true,true,""),List.of(item(now,true)),List.of(),false).contains("invalid_evidence_period"));assertTrue(check(draft(week.toString(),now.plusSeconds(1).toString(),List.of(id),List.of(forecast(List.of(id))),true,true,""),List.of(item(now,true)),List.of(),false).contains("invalid_evidence_period"));assertThrows(IllegalArgumentException.class,()->PublicationResearch.shape(draft(week.toString(),now.toString(),List.of(id,id),List.of(),true,true,"")));}
}
